t.script:
setTimeout(function(){
    var t = document.querySelector('.toast.show');
    if(t) t.classList.remove('show');
    if (window.history.replaceState) {
        var url = new URL(window.location.href);
        if (url.searchParams.has('error')) {
            url.searchParams.delete('error');
            window.history.replaceState({path: url.href}, '', url.href);
        }
    }
}, 5000);

div.script:
var currentCalData = ;

function switchTimesheetView(view) {
    var listCont = document.getElementById('timesheet_list_container');
    var calCont = document.getElementById('timesheet_calendar_container');
    var btnList = document.getElementById('btn_view_list');
    var btnCal = document.getElementById('btn_view_calendar');

    if (view === 'calendar') {
        if (listCont) listCont.style.display = 'none';
        if (calCont) calCont.style.display = 'block';
        if (btnList) {
            btnList.style.background = '#f1f5f9';
            btnList.style.color = '#4c1d95';
        }
        if (btnCal) {
            btnCal.style.background = '#4a148c';
            btnCal.style.color = '#ffffff';
        }
        renderCalendarGrid(currentCalData);
    } else {
        if (calCont) calCont.style.display = 'none';
        if (listCont) listCont.style.display = 'block';
        if (btnCal) {
            btnCal.style.background = '#f1f5f9';
            btnCal.style.color = '#4c1d95';
        }
        if (btnList) {
            btnList.style.background = '#4a148c';
            btnList.style.color = '#ffffff';
        }
    }
}

var selectedEmployeeId = currentCalData ? currentCalData.employee_id : null;

function onCalendarEmployeeChange(empId) {
    selectedEmployeeId = empId;
    var targetYear = currentCalData ? currentCalData.year : null;
    var targetMonth = currentCalData ? currentCalData.month : null;
    fetchCalendarData(targetYear, targetMonth, empId);
}

function navCalendarMonth(dir) {
    if (!currentCalData) return;
    var targetYear = (dir === 'prev') ? currentCalData.prev_year : currentCalData.next_year;
    var targetMonth = (dir === 'prev') ? currentCalData.prev_month : currentCalData.next_month;
    fetchCalendarData(targetYear, targetMonth, selectedEmployeeId);
}

function updateSummaryCard(data) {
    if (!data) return;
    function fmtHrs(val) {
        var v = val || 0;
        var h = Math.floor(v);
        var m = Math.round((v - h) * 60);
        return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
    }

    var titleEl = document.getElementById('summary_emp_month_title');
    if (titleEl) titleEl.innerText = (data.employee_name || '') + ' - ' + (data.month_name || '') + ' Summary';

    var reqEl = document.getElementById('sum_req_hrs');
    if (reqEl) reqEl.innerText = fmtHrs(data.monthly_required_hours) + ' Hrs';

    var lveEl = document.getElementById('sum_leave_hrs');
    if (lveEl) lveEl.innerText = fmtHrs(data.monthly_leave_hours) + ' Hrs';

    var netEl = document.getElementById('sum_net_req_hrs');
    if (netEl) netEl.innerText = fmtHrs(data.monthly_net_required) + ' Hrs';

    var logEl = document.getElementById('sum_logged_hrs');
    if (logEl) logEl.innerText = fmtHrs(data.monthly_regular_hours) + ' Hrs';

    var pctEl = document.getElementById('sum_comp_pct');
    if (pctEl) pctEl.innerText = (data.monthly_completion_pct || 0) + '%';
}

function fetchCalendarData(year, month, empId) {
    fetch('/my/timesheets/calendar_data', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: {
                year: year,
                month: month,
                employee_id: empId
            }
        })
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
        if (data && data.result) {
            currentCalData = data.result;
            selectedEmployeeId = currentCalData.employee_id;
            var monthTitle = document.getElementById('cal_month_title');
            if (monthTitle) monthTitle.innerText = currentCalData.month_name;

            var empSelect = document.getElementById('cal_employee_select');
            if (empSelect && selectedEmployeeId) {
                empSelect.value = selectedEmployeeId;
            }

            updateSummaryCard(currentCalData);
            renderCalendarGrid(currentCalData);
        }
    })
    .catch(function(err) { console.error("Calendar fetch error:", err); });
}

function renderCalendarGrid(data) {
    var tbody = document.getElementById('cal_grid_body');
    if (!tbody || !data || !data.days_data) return;

    tbody.innerHTML = '';
    var firstWeekday = data.first_weekday;
    var numDays = data.num_days;
    var daysData = data.days_data;

    var dayCounter = 1;
    var totalCells = firstWeekday + numDays;
    var totalRows = Math.ceil(totalCells / 7);

    for (var r = 0; r < totalRows; r++) {
        var tr = document.createElement('tr');
        for (var c = 0; c < 7; c++) {
            var cellIndex = r * 7 + c;
            var td = document.createElement('td');
            td.style.height = '90px';
            td.style.verticalAlign = 'top';
            td.style.padding = '6px';
            td.style.position = 'relative';

            if (cellIndex >= firstWeekday && dayCounter <= numDays) {
                var dayStr = data.year + '-' + String(data.month).padStart(2, '0') + '-' + String(dayCounter).padStart(2, '0');
                var dInfo = daysData[dayStr] || {};

                td.style.cursor = 'pointer';
                td.setAttribute('data-day-str', dayStr);

                var bgStyle = '#ffffff';
                var borderStyle = '1px solid #e2e8f0';
                var textStyle = '#334155';

                switch(dInfo.status_code) {
                    case 'green':
                        bgStyle = '#dcfce7';
                        borderStyle = '2px solid #22c55e';
                        textStyle = '#15803d';
                        break;
                    case 'red':
                        bgStyle = '#fee2e2';
                        borderStyle = '2px solid #ef4444';
                        textStyle = '#b91c1c';
                        break;
                    case 'yellow':
                        bgStyle = '#fef9c3';
                        borderStyle = '2px solid #eab308';
                        textStyle = '#a16207';
                        break;
                    case 'yellow_top_green_bottom':
                        bgStyle = 'linear-gradient(to bottom, #fef9c3 50%, #dcfce7 50%)';
                        borderStyle = '2px solid #22c55e';
                        textStyle = '#15803d';
                        break;
                    case 'yellow_top_red_bottom':
                        bgStyle = 'linear-gradient(to bottom, #fef9c3 50%, #fee2e2 50%)';
                        borderStyle = '2px solid #ef4444';
                        textStyle = '#b91c1c';
                        break;
                    case 'green_top_yellow_bottom':
                        bgStyle = 'linear-gradient(to bottom, #dcfce7 50%, #fef9c3 50%)';
                        borderStyle = '2px solid #22c55e';
                        textStyle = '#15803d';
                        break;
                    case 'red_top_yellow_bottom':
                        bgStyle = 'linear-gradient(to bottom, #fee2e2 50%, #fef9c3 50%)';
                        borderStyle = '2px solid #ef4444';
                        textStyle = '#b91c1c';
                        break;
                    default:
                        bgStyle = '#f8fafc';
                        borderStyle = '1px solid #f1f5f9';
                        textStyle = '#94a3b8';
                }

                td.style.background = bgStyle;
                td.style.border = borderStyle;
                td.style.borderRadius = '8px';

                function fmtHrs(val) {
                    var h = Math.floor(val);
                    var m = Math.round((val - h) * 60);
                    return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
                }

                var cellHtml = '<div class="d-flex justify-content-between align-items-center mb-1">';
                cellHtml += '<span style="font-weight: 700; font-size: 0.9rem; color: ' + textStyle + ';">' + dayCounter + '</span>';
                if (dInfo.scheduled_hours > 0 || dInfo.total_hours > 0) {
                    cellHtml += '<span class="badge" style="font-size: 0.7rem; background: rgba(255,255,255,0.85); color: #1e293b; border: 1px solid rgba(0,0,0,0.1); font-weight: 600;">' + fmtHrs(dInfo.total_hours) + ' / ' + fmtHrs(dInfo.scheduled_hours) + 'h</span>';
                }
                cellHtml += '</div>';

                if (dInfo.entries && dInfo.entries.length > 0) {
                    cellHtml += '<div style="font-size: 0.72rem; text-align: left; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">';
                    dInfo.entries.forEach(function(ent) {
                        cellHtml += '<div class="text-truncate" style="margin-bottom: 2px;">• ' + (ent.task || ent.project || ent.name) + ' (' + fmtHrs(ent.hours) + 'h)</div>';
                    });
                    cellHtml += '</div>';
                }

                td.innerHTML = cellHtml;

                (function(info) {
                    td.addEventListener('click', function() {
                        showDayDetailsModal(info);
                    });
                })(dInfo);

                dayCounter++;
            } else {
                td.style.background = '#f8fafc';
                td.style.border = '1px solid #f1f5f9';
                td.style.opacity = '0.4';
            }
            tr.appendChild(td);
        }
        tbody.appendChild(tr);
    }
}

function showDayDetailsModal(info) {
    if (!info) return;
    var titleEl = document.getElementById('dayModalTitle');
    var contentEl = document.getElementById('dayModalContent');
    if (titleEl) titleEl.innerText = 'Timesheets for ' + info.date;

    function fmtHrs(val) {
        var h = Math.floor(val);
        var m = Math.round((val - h) * 60);
        return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
    }

    var html = '<div class="mb-3 d-flex justify-content-between align-items-center p-2 rounded" style="background: #f1f5f9; font-size: 0.85rem;">';
    html += '<span>Scheduled: <strong>' + fmtHrs(info.scheduled_hours) + ' Hrs</strong></span>';
    html += '<span>Logged: <strong>' + fmtHrs(info.total_hours) + ' Hrs</strong></span>';
    html += '</div>';

    if (!info.entries || info.entries.length === 0) {
        html += '<p class="text-muted text-center py-3">No timesheet entries logged for this date.</p>';
    } else {
        html += '<div class="table-responsive"><table class="table table-sm table-hover mb-0" style="font-size: 0.85rem;">';
        html += '<thead style="background: #f8fafc;"><tr><th>Description</th><th>Project</th><th>Task</th><th class="text-end">Hours</th></tr></thead><tbody>';
        info.entries.forEach(function(e) {
            html += '<tr>';
            html += '<td>' + (e.name || '-') + (e.is_leave ? ' <span class="badge bg-warning text-dark ms-1">Time Off</span>' : '') + '</td>';
            html += '<td><span class="badge bg-light text-dark">' + (e.project || '-') + '</span></td>';
            html += '<td>' + (e.task || '-') + '</td>';
            html += '<td class="text-end font-weight-bold">' + fmtHrs(e.hours) + '</td>';
            html += '</tr>';
        });
        html += '</tbody></table></div>';
    }

    if (contentEl) contentEl.innerHTML = html;
    var modalEl = document.getElementById('dayDetailsModal');
    if (modalEl) {
        var modal = bootstrap.Modal.getInstance(modalEl) || new bootstrap.Modal(modalEl);
        modal.show();
    }
}

document.addEventListener('DOMContentLoaded', function() {
    document.addEventListener('click', function(e) {
        var headerRow = e.target.closest('.ts-group-header-row');
        if (headerRow) {
            var targetClass = headerRow.getAttribute('data-group-target');
            var icon = headerRow.querySelector('.ts-group-icon');
            var childRows = document.querySelectorAll('.' + targetClass);

            var isExpanded = false;
            childRows.forEach(function(row) {
                if (row.style.display === 'none' || row.style.display === '') {
                    row.style.display = 'table-row';
                    isExpanded = true;
                } else {
                    row.style.display = 'none';
                }
            });

            if (icon) {
                if (isExpanded) {
                    icon.classList.remove('fa-chevron-right');
                    icon.classList.add('fa-chevron-down');
                } else {
                    icon.classList.remove('fa-chevron-down');
                    icon.classList.add('fa-chevron-right');
                }
            }
        }
    });
});

document.addEventListener('DOMContentLoaded', function() {
    const projectSelect = document.getElementById('ts_project_id');
    const taskSelect = document.getElementById('ts_task_id');

    if(projectSelect && taskSelect) {
        projectSelect.addEventListener('change', function() {
            const projectId = this.value;
            if(!projectId) {
                taskSelect.innerHTML = '-- Select Project First --';
                taskSelect.disabled = true;
                return;
            }

            taskSelect.disabled = true;
            taskSelect.innerHTML = 'Loading tasks...';

            fetch('/my/timesheets/get_tasks_by_project', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: { project_id: projectId }
                })
            }).then(response => response.json())
              .then(data => {
                  taskSelect.innerHTML = '-- No Task --';
                  if(data.result && data.result.length > 0) {
                      data.result.forEach(task => {
                          taskSelect.innerHTML += `${task.name}`;
                      });
                  }
                  taskSelect.disabled = false;
              });
        });
    }
});
